style.css:
@-moz-document domain("genius.com") {
:root { color-scheme: dark !important; }

  /* ====================================================================
     Base surfaces  (both React + legacy "snarly" pages use <body>)
     ==================================================================== */
  html, body { background-color: #14181d !important; color: #c4cdd6 !important; }
  /* legacy page body variants paint #f7f7f7 / white */
  body.snarly, body[class*="cont-"], body.act-show { background-color: #14181d !important; }

  /* Soften every default light border to a subtle dark line */
  * { border-color: #262c33 !important; }

  /* Login / Sign-up hero: the page grid paints a decorative gradient (and, since the
     auth redesign, a solid white background-color) that washes the whole auth screen
     and hides the light "Sign In"/"Sign Up" title. Pin it to the dark base.
     NOTE: PageGrid-desktop is NOT only a layout wrapper. On a song page the
     annotation portal's grid carries the same class (AnnotationPortal-desktop__Grid):
     it is position:absolute, z-index:2, pointer-events:none and natively transparent,
     used solely to position the callout. Painting it opaque buries the entire lyrics
     column the moment an annotation opens. The exception below must stay. */
  [class*="PageGrid-desktop"] {
    background-color: #14181d !important; background-image: none !important; }

  /* Annotation portal grid: transparent overlay, must never be painted. */
  [class*="AnnotationPortal-desktop__Grid"] {
    background-color: transparent !important; }

  /* Mobile annotation reader: tapping a referent opens a ReactModal whose outer
     "Modal-mobile__Contents" is already darkened, but the inner annotation panel
     "BaseAnnotation-mobile__Container" ships pure white. Our typography lifts its
     body copy to light, so the whole annotation reads as light-on-white — nearly
     invisible. Darken the panel to the modal tone. The DESKTOP counterpart
     ("BaseAnnotation-desktop__Container") is natively transparent (it sits in the
     dark sidebar) and must stay untouched, so this is scoped to the mobile class. */
  [class*="BaseAnnotation-mobile__Container"] {
    background-color: #14181d !important; }
  /* The same mobile annotation reader shows the annotated lyric at the top as an
     "AnnotationLyrics__FragmentHighlight" — a pure-white highlight box with a light
     outline. Our ReferentFragment rules use a different class, so it stays white and the
     lifted light lyric text lands on white. Match the elevated referent tone, lift the
     text, and drop the light outline the modal draws around the lyric block. */
  [class*="AnnotationLyrics__FragmentHighlight"] {
    background-color: #21262d !important; color: #e6edf3 !important; }
  [class*="AnnotationLyrics__Container"],
  [class*="AnnotationLyrics__FragmentHighlight"] {
    outline-color: #2d333b !important; }

  /* Sign-in / Sign-up modal (nav "Sign Up", mobile menu): the panel is a brand-yellow
     card with black copy. Our lifted light text lands on the yellow at ~1.5:1, so the
     title, the "Or Sign Up with Email" divider and the terms line all disappear.
     Darken the card like every other floating surface; the copy is already light. */
  [class*="AuthenticationModal__Container"],
  [class*="Modal-desktop__Contents"], [class*="Modal-mobile__Contents"] {
    background-color: #14181d !important; background-image: none !important; }
  /* the "Join millions of contributors…" strapline is a plain <div> the site paints pure
     black (fine on the yellow card, invisible once it is dark) — the shared typography
     list only covers inline/text tags, so name it explicitly */
  [class*="AuthenticationFormComponents__Reason"],
  [class*="AuthenticationModal__Container"] div { color: #c4cdd6 !important; }

  /* ====================================================================
     MODERN (React / styled-components) shell
     ==================================================================== */

  /* ---- Sticky top nav: the site's brand bar (yellow on most pages, brand red on
     song pages) -> dark with a red accent ---- */
  [class*="StickyNav-desktop__Container"],
  [class*="StickyNav__Container"],
  [class*="StickyNav-mobile__Container"],
  [class*="StickyNavMobile"] {
    background-color: #0d1117 !important;
    border-bottom: 2px solid #ed4337 !important;
    color: #e6edf3 !important; }
  [class*="StickyNav-desktop__Subnavigation"],
  [class*="StickyNavSiteLinks"],
  [class*="StickyNav-desktop__Left"],
  [class*="StickyNav-desktop__Right"] { background-color: transparent !important; }
  [class*="StickyNavSectionLink__StyledLink"],
  [class*="StickyNav-desktop__AuthTextButton"],
  [class*="StickyNav-desktop__Auth"],
  [class*="StickyNav"] a { color: #e6edf3 !important; }
  /* the "Sign Up" text button (login/signup pages) ships black text -> lift both
     color and the webkit text-fill so it stays legible on the dark nav */
  [class*="StickyNav-desktop__AuthCustomTextButton"],
  [class*="StickyNav-desktop__AuthCustomTextButton"] * {
    color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }
  [class*="StickyNavSectionLink__StyledLink"]:hover,
  [class*="StickyNav"] a:hover { color: #ffffff !important; }
  /* Mobile hamburger menu: the flyout is a full-screen BRAND-YELLOW panel with black
     links and black social glyphs. Our nav rules lift the links to near-white, so on the
     yellow they land at ~1.2:1 and every menu item disappears. It only exists once the
     hamburger is tapped (and only on the mobile bundle), so no load-time scan sees it.
     Darken the panel like every other floating surface and lift the black glyphs. */
  [class*="StickyNav-mobile__Navigation"],
  [class*="StickyNavSiteLinks__MobileContainer"] {
    background-color: #14181d !important; }
  [class*="SocialLinks__Link"] svg, [class*="SocialLinks__Link"] svg path {
    fill: #c4cdd6 !important; }
  /* Every nav section link ships "border: 1px solid transparent" and the CURRENT section
     turns that border white — it is the only "you are here" cue. The blanket border reset
     paints all four sides of every link, so the whole nav renders as grey boxes and the
     active tab becomes indistinguishable. Clear them, then repaint the active one. */
  [class*="StickyNavSectionLink__StyledLink"] { border-color: transparent !important; }
  [class*="StickyNavSectionLink__StyledLink"][data-active="true"] {
    border-color: #ed4337 !important; color: #ffffff !important; }
  /* GENIUS wordmark: the inline SVG fill is black on some pages (home/charts) ->
     force light so it's visible on the dark header across all page types */
  [class*="PageHeaderLogo__Link"] svg, [class*="StickyNav-desktop__Logo"] svg,
  [class*="VideoListLogo__Link"] svg, [class*="PageHeaderLogo"] svg,
  [class*="PageHeaderLogo__Link"] svg path, [class*="StickyNav-desktop__Logo"] svg path,
  [class*="VideoListLogo__Link"] svg path, [class*="PageHeaderLogo"] svg path,
  [class*="PageHeaderLogo__Link"] svg use, [class*="PageHeaderLogo"] svg use,
  [class*="PageHeaderLogo__Link"] svg polygon, [class*="PageHeaderLogo"] svg polygon {
    fill: #e6edf3 !important; color: #e6edf3 !important; }
  /* nav search field */
  [class*="StickyNavSearch-desktop__Form"],
  [class*="StickyNavSearch"][class*="Form"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="StickyNavSearch-desktop__Input"],
  [class*="StickyNavSearch"][class*="Input"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  [class*="StickyNavSearch"] [class*="Input"]::placeholder { color: #8b949e !important; }
  [class*="StickyNavSearch-desktop__Icon"] svg,
  [class*="StickyNavSearch"] svg { fill: #c4cdd6 !important; color: #c4cdd6 !important; }
  /* Pageview eye icon (song rows / mini-cards / charts): eye.svg ships no fill on
     its paths, so it defaults to black and vanishes on the dark card. It sits right
     next to the pageview count; follow currentColor so it matches that count. */
  svg[src="eye.svg"], svg[src="eye.svg"] path {
    fill: currentColor !important; }
  /* nav search autocomplete dropdown: a white floating panel by default. Its
     result rows render in a same-origin genius.com/search/embed iframe, so the
     card/text rules below also apply inside it via @-moz-document. */
  [class*="PageHeaderDropdownMenu"],
  [class*="SearchDropdown"], [class*="search_dropdown"],
  .search_results, .quick_search-results {
    background-color: #1c2128 !important; border-color: #2d333b !important; color: #e6edf3 !important; }
  /* "Sign Up" is a zero-padding TEXT button on the live site, so painting it a
     solid brand-red box wraps the glyphs in a tight red rectangle (and white on
     #ed4337 is only 3.85:1). Keep it a text button and carry the brand red in
     the label, lifted so it clears 4.5:1 on the dark nav. */
  [class*="StickyNavSignUp__Button"],
  [class*="StickyNavSignUp__Button"] * {
    background-color: transparent !important; border-color: transparent !important;
    color: #f26659 !important; -webkit-text-fill-color: #f26659 !important; }
  [class*="StickyNavSignUp__Button"]:hover,
  [class*="StickyNavSignUp__Button"]:hover * {
    color: #ff8a7d !important; -webkit-text-fill-color: #ff8a7d !important; }

  /* ---- Song hero: bright-red gradient -> deep dark gradient w/ red tint ---- */
  [class*="SongHeader-desktop__Container"],
  [class*="SongHeader__Container"],
  [class*="SongHeader-mobile__Container"] {
    background-color: #14181d !important;
    background-image: linear-gradient(#1c2128, #14181d) !important;
    border-bottom: 1px solid #2d333b !important;
    color: #e6edf3 !important; }
  [class*="SongHeader-desktop__Title"],
  [class*="SongHeader"][class*="Title"] { color: #ffffff !important; }
  [class*="SongHeader-desktop__SongDetails"],
  [class*="SongHeader-desktop__Information"],
  [class*="SongHeader"] [class*="Credit"],
  [class*="SongHeader"] [class*="MetadataStats"] { color: #c4cdd6 !important; }

  /* ====================================================================
     Typography (shared)
     ==================================================================== */
  h1, h2, h3, h4, h5, h6,
  [class*="SectionTitle__Title"], [class*="LyricsHeader__Title"],
  [class*="SongInfo__Title"], [class*="RecommendedSongs__Header"],
  [class*="Comments__Title"], [class*="QuestionList__Header"],
  [class*="PrimaryAlbum__Title"], [class*="ContributorsCreditSong__Label"] {
    color: #e6edf3 !important; }
  p, li, dd, dt, span, td, th, label, figcaption, time, small, blockquote,
  [class*="RichText__Container"], [class*="RichText__Container"] *,
  [class*="ExpandableContent"], [class*="SongInfo__Container"],
  [class*="Answer__Body"], [class*="Answer__Body"] *,
  [class*="EditorialPlacement__Dek"], [class*="SectionTitle__Subtitle"],
  [class*="ChartSong"], [class*="ChartSong"] *,
  [class*="RecommendedSong"] [class*="Title"],
  [class*="RecommendedSong"] [class*="Artist"] { color: #c4cdd6 !important; }

  /* The "Credits" block and the "Other Albums" cards render their labels, values and
     artist-name separators in plain <div>s the site paints black / black-60% — the
     shared typography list above only covers inline/text tags, so they stay
     black-on-dark and read as blank columns. */
  [class*="Credit__Contributor"], [class*="Credit__Contributor"] div,
  [class*="OtherAlbum__Info"], [class*="OtherAlbum__ArtistNames"] { color: #c4cdd6 !important; }
  [class*="Credit__Label"], [class*="SongTags__Title"] { color: #8b949e !important; }

  /* lyrics-header label row "<Song> Lyrics" sits right after the ⓘ info icon
     and is a non-link title the site paints near-black via -webkit-text-fill
     (defaults to currentColor) -> lift BOTH color and the webkit text-fill so it
     stays legible on the dark bar even if the site ships an !important fill */
  [class*="LyricsHeader__TitleContainer"], [class*="LyricsHeader__GroupContainer"],
  [class*="LyricsHeader__Title"], [class*="LyricsHeader__TitleContainer"] * {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }

  /* ---- Links: keep the Genius periwinkle, lifted for dark contrast ---- */
  a, a span { color: #9aa7f0 !important; }
  a:hover { color: #c2cbff !important; }

  /* ====================================================================
     Action / UI icons (inline SVG) — black on the light site, invisible on
     dark. Lift the action-icon families to a legible light fill. The GENIUS
     wordmark, yellow IQ badges and brand-colored surfaces are handled
     elsewhere and are NOT in these families, so they stay intact.
     ==================================================================== */
  [class*="Button__Container"] svg, [class*="Button__Container"] svg path,
  [class*="ShareButtons__Container"] svg, [class*="ShareButtons__Container"] svg path,
  [class*="LyricsFooter"] svg, [class*="LyricsFooter"] svg path,
  [class*="VotingActions__Button"] svg, [class*="VotingActions__Button"] svg path,
  [class*="DropdownList__Icon"] svg, [class*="DropdownList__Icon"] svg path,
  [class*="Dropdown__Toggle"] svg, [class*="Dropdown__Toggle"] svg path,
  [class*="ContributorsCreditSong__Label"] svg, [class*="ContributorsCreditSong__Label"] svg path,
  [class*="InfoTooltip__Container"] svg, [class*="InfoTooltip__Container"] svg path,
  [class*="MetadataTooltip"] svg, [class*="MetadataTooltip"] svg path,
  [class*="LyricsHeader__Container"] svg, [class*="LyricsHeader__Container"] svg path,
  [class*="RoleIcon__Container"] svg, [class*="RoleIcon__Container"] svg path,
  [class*="InlineSvg__Wrapper"] svg, [class*="InlineSvg__Wrapper"] svg path {
    fill: #c4cdd6 !important; color: #c4cdd6 !important; }
  /* brand share glyphs (Facebook/Twitter) keep their own brand color, just
     ensure they're not pure-black-on-dark — lift to a light neutral too */
  [class*="ShareButtons__Container"] [aria-label*="Facebook"] svg path,
  [class*="ShareButtons__Container"] [aria-label*="Twitter"] svg path { fill: #c4cdd6 !important; }
  /* Verified-artist avatar (LyricsHeader byline / artist cards): the "verified" cue is a
     brand-yellow disc checkmark ("VerifiedInlineAvatar__CircleCheckMark": a yellow <circle>
     + a black <path> tick) plus a yellow ring on the avatar. The disc sits inside a
     "Button__Container", so the action-icon rule above greys the whole svg, and the blanket
     border reset greys the ring — the badge renders as a flat grey blob and the artist reads
     as unverified. Restore the yellow disc (the circle inherits the svg fill), keep the tick
     dark for contrast, and repaint the ring yellow. Scoped to the -Verified- class only. */
  [class*="VerifiedInlineAvatar__Container"] [class*="CircleCheckMark"] {
    fill: #ffff64 !important; }
  [class*="VerifiedInlineAvatar__Container"] [class*="CircleCheckMark"] path {
    fill: #14181d !important; }
  [class*="VerifiedInlineAvatar__Avatar"] { border-color: #ffff64 !important; }

  /* ====================================================================
     Lyrics body + annotations (referents)
     ==================================================================== */
  [data-lyrics-container],
  [class*="Lyrics__Container"],
  [class*="Lyrics__Root"] { color: #e6edf3 !important; background-color: transparent !important; }
  [data-lyrics-container] a { color: #e6edf3 !important; } /* inline section labels */

  /* annotated (referent) words: light grey highlight -> subtle dark elevated */
  [class*="ReferentFragment-desktop__Highlight"],
  [class*="ReferentFragment"][class*="Highlight"],
  [class*="ReferentFragment-desktop__ClickTarget"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  [class*="ReferentFragment-desktop__Highlight"]:hover,
  [class*="ReferentFragment"][class*="Highlight"]:hover {
    background-color: #2d333b !important; }
  /* the active annotation gets the brand-red left accent */
  [class*="ReferentFragment"][class*="Highlight"][class*="active"],
  [class*="Referent"][class*="--active"] {
    background-color: #21262d !important; box-shadow: inset 3px 0 0 #ed4337 !important; }
  /* the open-annotation callout caret (the diamond pointing from the lyric to the
     annotation panel) is a rotated ::before square painted pure white with a light
     two-tone border -> match the dark panel surface so it reads as a subtle pointer */
  [class*="AnnotationPortal-desktop__Callout"]::before,
  [class*="AnnotationPortal"][class*="Callout"]::before {
    background-color: #14181d !important; border-color: #2d333b !important; }

  /* ---- Right sidebar / annotation panel ---- */
  [class*="RightSidebar__Container"],
  [class*="Sidebar__Container"],
  [class*="LyricsSidebarAd"] { background-color: transparent !important; }
  [class*="RecommendedSong__Container"],
  [class*="RecommendedSongs__Container"] { background-color: transparent !important; }
  [class*="RecommendedSong__Container"]:hover { background-color: #1c2128 !important; }
  /* annotation attribution "<N> contributors": a <button> (not <a>, so the link rule
     misses it) the site paints pure black via -webkit-text-fill-color — invisible on
     the dark annotation panel for the active/open annotation. Lift to the link tone. */
  [class*="Attribution__Container"] [class*="TextButton"],
  [class*="Attribution__Container"] [class*="TextButton"] * {
    color: #9aa7f0 !important; -webkit-text-fill-color: #9aa7f0 !important; }

  /* ====================================================================
     Cards / panels that default to white
     ==================================================================== */
  [class*="QuestionTemplate__Title"],
  [class*="MetadataQuestionTemplate__Title"],
  [class*="QuestionList__Table"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; }
  /* Q&A question rows are brand-red on the live site and their expand/collapse glyph keeps
     that red, so flattening the title to plain light text leaves a red glyph beside a grey
     heading and drops the cue that the row opens. Restore the red, lifted to clear 4.5:1 on
     the card. Anchored with [class^=] because the substring above also matches
     "MetadataQuestionTemplate__Title", which the site paints black and must stay light. */
  [class^="QuestionTemplate__Title"],
  [class^="QuestionTemplate__Title"] *,
  [class^="QuestionTemplate__Container"] [class*="ExpandButton"],
  [class^="QuestionTemplate__Container"] [class*="ExpandButton"] svg,
  [class^="QuestionTemplate__Container"] [class*="ExpandButton"] path {
    color: #f26659 !important; fill: #f26659 !important;
    -webkit-text-fill-color: #f26659 !important; }
  [class*="QuestionTemplate__Container"],
  [class*="MetadataQuestionTemplate__Container"],
  [class*="Answer__Container"],
  [class*="Comments__Container"],
  [class*="SongCommentsWithAds__Container"],
  [class*="SongDescription__Container"],
  [class*="About__Container"],
  [class*="MusicVideo__Container"],
  [class*="PrimaryAlbum__Container"],
  [class*="AlbumTracklist__Container"] {
    background-color: transparent !important; color: #c4cdd6 !important; }
  [class*="CommentForm__FakeTextField"],
  [class*="SongCommentsWithAds__CTA"] {
    background-color: #1c2128 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  /* "This song bio is unreviewed" banner (SongDescription / annotation): the site flags
     pending content with a white + light-pink candy-stripe background, a pink border and a
     pink "unreviewed" explainer toggle. The stripe's white bands glare as a light slab on
     the dark page, and the blanket border reset + the shared span rule grey out the pink
     border and the toggle, erasing the pending signal. Re-stripe on the dark base with a
     faint pink tint and restore the pink accent (lifted to clear 4.5:1). */
  [class*="UnreviewedAnnotation__Unreviewed"] {
    background-image: repeating-linear-gradient(45deg, #14181d, #14181d 7px, #2a1a22 7px, #2a1a22 14px) !important;
    border-color: #ff3d7f !important; }
  [class*="UnreviewedAnnotation__Unreviewed"],
  [class*="UnreviewedAnnotation__Unreviewed"] * {
    color: #ff3d7f !important; -webkit-text-fill-color: #ff3d7f !important; }

  /* ---- Apple Music player strip / media ---- */
  [class*="AppleMusicPlayer"] { background-color: #1c2128 !important; }
  /* ...but "AppleMusicPlayer-desktop__PageGrid" and "MediaPlayersContainer__Container" are
     the full-width LAYOUT grid around the 940px player, natively transparent (the grid is
     even pointer-events:none). Painting them draws an elevated band bleeding 170px past
     the player on each side. Only the IframeContainer is a real surface. */
  [class*="AppleMusicPlayer-desktop__PageGrid"],
  [class*="AppleMusicPlayer-mobile__PageGrid"],
  [class*="MediaPlayersContainer__Container"] { background-color: transparent !important; }
  /* The actual player UI renders in a same-origin genius.com/songs/<id>/apple_music_player
     iframe, so domain("genius.com") matches inside it. Its container/player/popup paint
     pure white by default -> dark; the divider is pure black -> soften to a dark line. */
  .apple_music_player-container, .apple_music_player-player,
  .apple_music_player-player-popup { background-color: #1c2128 !important; }
  .apple_music_player-divider { background-color: #2d333b !important; }
  /* Seekbar chrome is drawn for a WHITE player: the track is a pure-black ::before bar
     (invisible to element-bg scans) and the scrubber knob is a pure-black disc, both
     black-on-dark once the strip is themed. The Apple Music wordmark path is black too. */
  .apple_music_player-seekbar::before { background-color: #4a525c !important; }
  .apple_music_player-seekbar-scrubber-circle { background-color: #e6edf3 !important; }
  .apple_music_player-logo path,
  .apple_music_player-expanded_header-logo path { fill: #c4cdd6 !important; }
  /* "Featured Videos" module (artist/album pages) is a same-origin Primis video player
     served in a genius.com iframe. Our body rule darkens its document, but the inner
     #largeUnit slate stays pure white and frames the video with glaring white bands
     (the header label row + the gap above the thumbnail strip) -> darken the slate. */
  #largeUnit, .Large-unit, [class*="primis"] #largeUnit { background-color: #14181d !important; }

  /* ---- Tags / chips ---- */
  [class*="SongTags__Tag"], [class*="SquareManySelects__Container"],
  [class*="SquareSelectTitle__Container"], [class*="SquareManySelects__Select"] {
    background-color: #1c2128 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  [class*="SongTags__Tag"]:hover { background-color: #2d333b !important; }
  /* "SongTags__TagContainer" is the transparent flex wrapper AROUND the chips, not a chip;
     the substring above swallows it and paints a grey slab behind the whole tag row. */
  [class*="SongTags__TagContainer"] { background-color: transparent !important; }

  /* ---- Buttons ---- */
  [class*="Button__Container"], [class*="VotingActions__Button"],
  [class*="ExpandableContent__Button"], [class*="List__More"],
  [class*="SquareButton"], [class*="Charts__LoadMore"] button {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  /* The "*__LoadMore" and "ExpandableContent__ButtonContainer" classes sit on the
     full-width GRID WRAPPER around the button, not on the button — giving them the
     button surface paints a long grey slab behind (and level with) the button. They
     are transparent on the live site; keep them that way. */
  [class*="Charts__LoadMore"], [class*="Latest-desktop__LoadMore"],
  [class*="Community-desktop__LoadMore"], [class*="Videos-desktop__LoadMore"],
  [class*="ExpandableContent__ButtonContainer"] {
    background-color: transparent !important; }
  [class*="SquareButton"] *, [class*="Charts__LoadMore"] * { color: #e6edf3 !important; }
  [class*="Button__Container"]:hover, [class*="VotingActions__Button"]:hover {
    background-color: #2d333b !important; }
  /* dropdown pointer: an 11px square rotated 45deg, painted pure white */
  [class*="DropdownList__Caret"] {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  [class*="DropdownList__ItemsContainer"], [class*="Dropdown__ContentContainer"],
  [class*="DropdownList__Item"], [class*="DropdownList__LabeledButton"] {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  [class*="DropdownList__Item"]:hover { background-color: #2d333b !important; }

  /* ---- Hover tooltips (artist cards, the ⓘ metadata popup) ----
     "PortalTooltip__Container" / "InfoTooltip__Container" / "MetadataTooltip__InfoTooltip"
     are the inline TRIGGER wrappers (a 12x21 icon box, an 88x16 credit name), natively
     transparent — painting them draws a lighter rectangle behind every contributor name
     and every ⓘ. The floating panel is a separate portal node, "TooltipShadow". */
  [class*="PortalTooltip__Container"], [class*="InfoTooltip__Container"],
  [class*="MetadataTooltip__InfoTooltip"], [class*="LyricsHeader__MetadataTooltip"] {
    background-color: transparent !important; }
  /* The panel ships pure white for a normal artist and brand-yellow for a verified one —
     both keep black text, so our lifted light text lands unreadable on them. The two
     variants differ only by a build-volatile styled-components hash, so darken both and
     carry the verified signal on its own stable "Verified" eyebrow, in the brand yellow. */
  [class*="TooltipShadow"] {
    background-color: #1c2128 !important; background-image: none !important;
    border-color: #2d333b !important; }
  [class*="ArtistTooltip__Container"], [class*="ArtistTooltip__Container"] * {
    color: #c4cdd6 !important; -webkit-text-fill-color: #c4cdd6 !important; }
  [class*="ArtistTooltip__ArtistTooltipName"] {
    color: #9aa7f0 !important; -webkit-text-fill-color: #9aa7f0 !important; }
  [class*="ArtistTooltip__Verified"] {
    color: #ffff64 !important; -webkit-text-fill-color: #ffff64 !important; }
  /* The ⓘ lyrics-metadata popup is a Radix popover ("TooltipContent" with its own
     "TooltipArrow" div), NOT the "TooltipShadow" panel the artist card uses: it ships a
     pure-white card with a white arrow and black line rows, so our lifted light text
     lands on white and the whole popup reads blank. It only exists while the ⓘ is
     hovered, so no load-time scan sees it. Darken panel + arrow and lift the rows. */
  [class*="TooltipContent"] {
    background-color: #1c2128 !important; background-image: none !important;
    border-color: #2d333b !important; }
  [class*="TooltipArrow"] { background-color: #1c2128 !important; }
  [class*="InfoTooltip__InfoTooltipLine"],
  [class*="InfoTooltip__LineText"] { color: #c4cdd6 !important; }

  /* ====================================================================
     Homepage modules
     ==================================================================== */
  [class*="HomeContent-desktop__Section"],
  [class*="HomeContent-desktop__Container"],
  [class*="HomeContent"] { background-color: transparent !important; }
  [class*="ChartItem-desktop__Row"], [class*="ChartItem"][class*="Row"],
  [class*="EditorialPlacement__Container"], [class*="TopContent-desktop__Placement"],
  [class*="Latest-desktop__Placement"], [class*="Videos-desktop__Hero"],
  [class*="CommunityRanking-desktop__Row"], [class*="Community-desktop__User"] {
    background-color: transparent !important; }
  [class*="ChartItem-desktop__Row"]:hover, [class*="EditorialPlacement__Container"]:hover {
    background-color: #1c2128 !important; }
  [class*="ChartSong-desktop__Title"], [class*="EditorialPlacement__Title"] { color: #e6edf3 !important; }
  /* Homepage news cards repeat the article-link underline-skip trick on hover: a black
     1px background-image "underline" plus a WHITE text-shadow halo (out to .15em) that
     punches gaps around the glyphs so the rule skips descenders. On the dark card the
     black underline vanishes and the fat white halo floods the letters into a blob.
     Re-point the halo at the hovered card surface and the underline at the title tone.
     Keeping the halo (rather than dropping it) preserves the descender skip. */
  [class*="EditorialPlacement__Link"]:hover [class*="EditorialPlacement__Title"] h2,
  [class*="EditorialPlacement__Link"]:hover [class*="EditorialPlacement__Title"] h3 {
    color: #e6edf3 !important;
    background-image: linear-gradient(#e6edf3, #e6edf3) !important;
    text-shadow: 0.03em 0 #1c2128, -0.03em 0 #1c2128, 0 0.03em #1c2128, 0 -0.03em #1c2128,
                 0.06em 0 #1c2128, -0.06em 0 #1c2128, 0.09em 0 #1c2128, -0.09em 0 #1c2128,
                 0.12em 0 #1c2128, -0.12em 0 #1c2128, 0.15em 0 #1c2128, -0.15em 0 #1c2128 !important; }
  [class*="ChartSong-desktop__Artist"], [class*="EditorialPlacement__Author"],
  [class*="EditorialPlacement__PublishedAt"], [class*="ChartSong-desktop__Metadatum"] { color: #8b949e !important; }
  /* red eyebrow label — the word sits in a <span> inside the card's <a>, so the generic
     "a span" link rule repaints it periwinkle unless the descendant is named too */
  [class*="EditorialPlacement__Label"],
  [class*="EditorialPlacement__Label"] * { color: #ed4337 !important; }
  [class*="UserBadge__Name"] { color: #c4cdd6 !important; }
  [class*="UserBadge__Role"], [class*="Community-desktop__Iq"], [class*="CommunityRanking-desktop__Iq"] { color: #8b949e !important; }
  /* Section eyebrows ("MOST RECENT NEWS", "GENIUS ORIGINAL SERIES") and the community
     leaderboard's IQ scores are the site's accent colour, carried on a stable
     color="accent.main" attribute (the value itself lives on a build-volatile
     styled-components hash). The blanket h1-h6 rule greys the eyebrows and the "a span"
     link rule repaints the IQ scores periwinkle, so the accent is lost either way.
     Accent is section-scoped: brand pink everywhere, brand yellow in the Videos band
     (#videos). The pink is lifted from #ff1464 (4.4:1) to clear 4.5:1 on the base. */
  [class*="HomeContent"] [color="accent.main"],
  [class*="HomeContent"] [color="accent.main"] * {
    color: #ff3d7f !important; -webkit-text-fill-color: #ff3d7f !important; }
  #videos [color="accent.main"], #videos [color="accent.main"] * {
    color: #ffff64 !important; -webkit-text-fill-color: #ffff64 !important; }

  /* ====================================================================
     LEGACY ("snarly") pages — artist + search results
     ==================================================================== */
  /* legacy top nav */
  .header, .header-inner, .header_nav, .header_with_login {
    background-color: #0d1117 !important; border-bottom: 2px solid #ed4337 !important; color: #e6edf3 !important; }
  .header a, .header_nav a, .header_nav-menu_item, .logo_link { color: #e6edf3 !important; }
  .header a:hover { color: #ffffff !important; }
  /* legacy GENIUS wordmark is a dark raster sprite in ::before -> invert to light */
  .logo_link::before, .header_logo::before, a.logo::before {
    filter: invert(1) brightness(1.9) !important; }
  .logo_link, .header_logo { color: #e6edf3 !important; }
  .header_search-input, input.header_search-input, .search_input {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .header_search-input::placeholder { color: #8b949e !important; }

  /* containers / cards */
  .white_container, .mini_card, .mini_article_card, .thumbnail_grid,
  .standalone_annotation, .song_card, .vertical_album_card, .full_width_container--white,
  .horizontal_album_card, .leaderboard, .feed_item, .annotation_sidebar_unit,
  .article_card, .text_card, .cosign_unit, .user_badge,
  .profile_contribution, .full_width_link, .full_width_card, .grid_video {
    background-color: #1c2128 !important; color: #c4cdd6 !important; border-color: #2d333b !important; }
  .full_width_link, .full_width_link * { color: #c4cdd6 !important; }
  /* legacy "gray_container" (album/article comment boxes, the ellipsis menu, the
     bottom strip) paints rgba(204,204,204,.2) — a translucent light wash that turns
     into a washed-out grey slab over the dark base. Make it a normal dark card. */
  .gray_container, .comments.gray_container, .ellipsis_menu.gray_container {
    background-color: #1c2128 !important; }
  .mini_card:hover, .mini_article_card:hover, .song_card:hover { background-color: #21262d !important; }
  .full_width_container { background-color: transparent !important; }
  /* Album-tracklist / chart rows draw their divider on a full-bleed ::before carrying a
     near-white border. The blanket border reset at the top of the file is `*`, which does
     NOT match pseudo-elements, so that line survives and paints a bright bar across the
     whole left gutter beside every dark row divider. */
  .chart_row::before, .chart_row::after { border-color: #262c33 !important; }
  /* legacy 404 / error page: the render_404 panel keeps a pure-white background while
     our typography rules already lift its headline + copy to light -> light-on-white =
     invisible title. Darken the panel so the error text reads. */
  .render_404, [class*="render_404"] { background-color: #14181d !important; }
  /* the 404 "sgnarly" mascot is a black-on-white raster GIF that renders as a glaring
     white square on the dark error page -> invert so it reads as a light mascot on dark.
     Inverting turns the GIF's white ground pure black, which is a visible square against
     #14181d; "lighten" then lets the (lighter) page show through the black ground while
     the now-white mascot still wins per channel. */
  .render_404-image, img.render_404-image {
    filter: invert(1) !important; mix-blend-mode: lighten !important; }

  /* legacy editorial article / news page (<article-page>): the .grid_layout content
     wrapper inside the dark .white_container stays pure-white, and the byline/share
     "info_and_action_box" panels are white too -> dark so the body copy (already
     lifted to light) is readable. The article title uses an "outline" variant with a
     black -webkit-text-stroke for legibility over the hero image; on the dark body it
     would render as black-outlined light text -> drop the black stroke so it reads. */
  article-page .grid_layout { background-color: transparent !important; }
  .article_info_and_action_box {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  /* the .article_rich_text_formatting body wrapper sets its OWN #333 text color, which
     the inline emphasis tags the shared typography list omits (<center>, <strong>, <b>,
     legacy <font>) inherit -> dark-on-dark intro/lead lines on the dark article card.
     Lift the wrapper to the readable body tone; inline links keep their periwinkle rule. */
  .article_rich_text_formatting, .article_rich_text_formatting center,
  .article_rich_text_formatting strong, .article_rich_text_formatting b,
  .article_rich_text_formatting font {
    color: #c4cdd6 !important; }
  .article_title, .article_title--o {
    -webkit-text-stroke: 0 !important; color: #e6edf3 !important; -webkit-text-fill-color: #e6edf3 !important; }
  /* article body + sidebar reference links fake an underline-skip: a black 1px
     background-image "underline" plus a WHITE text-shadow halo punched around each
     glyph. On dark the underline vanishes and the white halo outlines every letter,
     so the links read as double-struck. Re-point both at the card surface / link hue. */
  .article_reference_link, .article_rich_text_formatting a {
    background-image: linear-gradient(#9aa7f0, #9aa7f0) !important;
    text-shadow: 0.84px 0 0 #1c2128, -0.84px 0 0 #1c2128,
                 1.68px 0 0 #1c2128, -1.68px 0 0 #1c2128 !important; }

  /* legacy text colors (#222 / #444) -> light */
  .mini_card-title, .mini_article_card-title, .song_card-title,
  .vertical_album_card-album_name, .text_label, .profile_identity-name,
  .list_section-header_label, .metadata_unit-info, .header_with_cover_art-primary_info_title {
    color: #e6edf3 !important; }
  .mini_card-subtitle, .mini_article_card-subtitle, .song_card-info,
  .vertical_album_card-artist_name, .metadata_unit-label, .text_2, .small_text,
  .u-quarter_top_margin, .secondary_info { color: #c4cdd6 !important; }
  .mini_card_grid-title, .list_section .text_label { color: #e6edf3 !important; }
  /* "More on Genius" recirculated article cards: titles ship near-black (#222) and
     vanish on dark -> lift; the date/meta line to the muted secondary tone */
  .recirculated_content-title { color: #e6edf3 !important; }
  .recirculated_content-subtitle, .recirculated_content-date,
  .recirculated_content-author { color: #c4cdd6 !important; }

  /* legacy profile header is already dark — keep it, just soften */
  .profile_header { background-color: #0d1117 !important; }
  .profile_tabs-tab--selected { border-bottom-color: #ed4337 !important; color: #ffffff !important; }
  /* The blanket border reset above repaints EVERY border, including the ones the site
     uses as accents rather than as dividers: the coloured 2px underline that marks a
     "text_label--<colour>" link-button, and the ring around the profile avatar.
     The avatar ring is NOT decorative: the site paints it green for a VERIFIED artist
     (.profile_header-avatar--verified) and white otherwise, so pinning every ring to
     white erased the verified signal. Restore the ring per state. */
  .profile_header-avatar { border-color: #e6edf3 !important; }
  .profile_header-avatar--verified { border-color: #38ef51 !important; }

  /* Legacy semantic label colours. ".text_label" sits in the light-text list above, so
     EVERY colour variant the site ships (pink / verified-green / green / red / yellow /
     purple / gray / white — enumerated from bagon_desktop.css) was flattened to one
     grey: the verified-annotations CTA, the "See All" alternate-names link, the pink
     tab counts. Restore each, and the matching --button underline with it. Pink is
     lifted from #ff1464 (4.4:1) and red from #ff1414 (4.3:1) to clear 4.5:1 on dark. */
  .text_label.text_label--pink, .text_label.text_label--pink *,
  .profile_tabs-tab-count, .profile_identity-alternate_names-see_all {
    color: #ff3d7f !important; }
  .text_label.text_label--pink { border-bottom-color: #ff3d7f !important; }
  .text_label.text_label--red, .text_label.text_label--red * { color: #ff4d4d !important; }
  .text_label.text_label--red { border-bottom-color: #ff4d4d !important; }
  .text_label.text_label--verified, .text_label.text_label--verified * { color: #38ef51 !important; }
  .text_label.text_label--verified { border-bottom-color: #38ef51 !important; }
  .text_label.text_label--green, .text_label.text_label--green * { color: #0ecb27 !important; }
  .text_label.text_label--green { border-bottom-color: #0ecb27 !important; }
  .text_label.text_label--yellow, .text_label.text_label--yellow * { color: #ffff64 !important; }
  .text_label.text_label--yellow { border-bottom-color: #ffff64 !important; }
  .text_label.text_label--purple, .text_label.text_label--purple * { color: #9aa7f0 !important; }
  .text_label.text_label--purple { border-bottom-color: #9aa7f0 !important; }
  .text_label.text_label--gray, .text_label.text_label--gray * { color: #9a9a9a !important; }
  .text_label.text_label--gray { border-bottom-color: #9a9a9a !important; }
  /* annotation "Read More" affordance ships the periwinkle link hue; the shared span
     rule greys it, so it stops reading as clickable */
  .truncated_annotation_text-read_more { color: #9aa7f0 !important; }
  /* contributor leaderboard: the rank, the username and the IQ score are the periwinkle
     accent, greyed by the shared span rule — the column reads as plain metadata without it */
  .leaderboard-rank, .leaderboard-rank *,
  .leaderboard-sort_value, .leaderboard-sort_value *,
  .leaderboard-user, .leaderboard-user *,
  .header_with_cover_art-pyongs_count { color: #9aa7f0 !important; }
  /* the periwinkle-filled count pill carries a 2px border in its OWN fill colour (so it
     reads as a solid pill); the blanket border reset draws a dark ring around it */
  .numbered_indicator--purple_filled { border-color: #99a7ee !important; }

  /* legacy buttons / tags */
  .normal_button, .text_button, .quinary_button, .tag,
  .square_button, .full_width_button {
    background-color: #21262d !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .normal_button:hover, .text_button:hover, .square_button:hover, .full_width_button:hover { background-color: #2d333b !important; }
  .tag:hover { background-color: #2d333b !important; }
  .square_button *, .full_width_button * { color: #e6edf3 !important; }
  /* Brand share / artist-social buttons. The neutral ".square_button" surface above has
     the same specificity and comes first, so it SWALLOWED every brand fill the site
     ships (facebook/twitter/instagram/google/spotify/apple/email) and the buttons all
     rendered as identical grey boxes — the earlier "keeps their brand bg" comment was
     simply wrong. Re-assert each brand fill with a two-class selector so it wins.
     Instagram/Apple are brand-black: keep the fill but give them a visible edge, or the
     button reads as a hole punched in the dark page. */
  .square_button.square_button--facebook { background-color: #3b5998 !important; border-color: #3b5998 !important; }
  .square_button.square_button--twitter { background-color: #55acee !important; border-color: #55acee !important; }
  .square_button.square_button--google { background-color: #dd4b39 !important; border-color: #dd4b39 !important; }
  .square_button.square_button--spotify { background-color: #2ebd59 !important; border-color: #2ebd59 !important; }
  .square_button.square_button--email { background-color: #9a9a9a !important; border-color: #9a9a9a !important; }
  .square_button.square_button--instagram,
  .square_button.square_button--apple { background-color: #000000 !important; border-color: #2d333b !important; }
  .square_button--facebook, .square_button--twitter, .square_button--google,
  .square_button--instagram, .square_button--spotify, .square_button--apple, .square_button--email {
    color: #ffffff !important; }
  /* the "--purple" variant is an accent icon button (the annotation/contribution expand
     caret): the site carries the periwinkle in its glyph, which the neutral .square_button
     rule above flattens to the same light grey as every other button */
  .square_button.square_button--purple,
  .square_button.square_button--purple * { color: #9aa7f0 !important; fill: #9aa7f0 !important; }
  .square_button--facebook *, .square_button--twitter *, .square_button--google *,
  .square_button--instagram *, .square_button--spotify *, .square_button--apple *,
  .square_button--email * { color: #ffffff !important; }
  /* legacy inline action-button glyphs — the pyong (IQ lightning) button and the
     header search magnifier ship a pure-black SVG fill that vanishes on the dark
     surfaces. Lift them to a legible light neutral. The FB/Twitter share glyphs
     carry their own brand color and aren't in these families, so they stay intact. */
  .pyong_button svg, .pyong_button svg path,
  .global_search-submit_button svg, .global_search-submit_button svg path,
  .header_search-submit svg, .header_search-submit svg path {
    fill: #c4cdd6 !important; color: #c4cdd6 !important; }

  /* Genius IQ badges: keep the signature yellow fill, dark text for contrast */
  .tag_label--yellow_background, [class*="tag_label--yellow"],
  .profile_identity-iq, .user_badge-iq {
    background-color: #ffff64 !important; color: #14181d !important; }
  .tag_label--yellow_background *, [class*="tag_label--yellow"] *,
  .profile_identity-iq *, .user_badge-iq * { color: #14181d !important; }

  /* periwinkle count chips: keep accent bg, dark label for contrast */
  .profile_contributions_group-count, .profile_contributions_group-count * { color: #14181d !important; }

  /* legacy contribution vote score ("+1793" between the thumb buttons): the site paints
     it green when net-positive and red when negative — a real sentiment cue. It carries
     "square_button", so the neutral .square_button color rule above flattens both to grey
     and the up/down signal is lost. Restore it, lifted for contrast on the dark card. */
  .voting-total--positive, .voting-total--positive * { color: #3fb950 !important; }
  .voting-total--negative, .voting-total--negative * { color: #f85149 !important; }

  /* legacy active header tab: yellow underline -> brand red */
  .header-primary.active, .header_with_login .active {
    background-color: transparent !important; box-shadow: inset 0 -3px 0 #ed4337 !important; }

  /* legacy avatar / image placeholders */
  .user_avatar, .profile_header-avatar, .avatar { background-color: #1c2128 !important; }

  /* legacy "STATS" panel (charts / profile contributor pane): white card with black
     glyph icons + #666 labels -> dark card, light icons, legible labels */
  .statistics_panel { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .statistics_panel svg, .statistics_panel svg path { fill: #c4cdd6 !important; }
  .statistic_and_label-number { color: #e6edf3 !important; }
  .statistic_and_label-subtext { color: #8b949e !important; }

  /* legacy dropdowns / menus */
  .dropdown_menu, .dropdown_menu-item, .menu {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  .dropdown_menu-item:hover { background-color: #2d333b !important; }
  /* the legacy flyout menu (profile "All contributions", and the other docked menus) is a
     white .tooltip panel with black <div> rows — the shared typography list covers inline
     tags only, so it stays a glaring white card. It only exists once opened. */
  .tooltip { background-color: #1c2128 !important; border-color: #2d333b !important; }
  .tooltip-list_item, .tooltip-list_item * { color: #e6edf3 !important; }
  .tooltip-list_item:hover { background-color: #2d333b !important; }
  /* legacy search autocomplete: the feed_dropdown panel paints #f7f7f7 behind the
     result rows -> dark so the section-header bands stop flashing white */
  .feed_dropdown, .feed_dropdown--medium_width {
    background-color: #1c2128 !important; border-color: #2d333b !important; }
  .feed_dropdown .section_header, .feed_dropdown-section_header,
  .feed_dropdown .text_label { color: #8b949e !important; }

  /* legacy lyric annotation highlight */
  .referent, a.referent { background-color: #1c2128 !important; color: #e6edf3 !important; }
  .referent--yellow, .referent.referent--yellow { background-color: #21262d !important; box-shadow: inset 3px 0 0 #ed4337 !important; }
  /* standalone annotation (artist profile contributions): the caret pointing to the
     card is a rotated ::before square painted pure white -> match the card surface */
  .standalone_annotation { background-color: #1c2128 !important; }
  .standalone_annotation-referent_fragment--with_caret::before,
  .standalone_annotation-referent_fragment::before { background-color: #1c2128 !important; }

  /* ====================================================================
     Forms / inputs (shared)
     ==================================================================== */
  input, textarea, select {
    background-color: #1c2128 !important; color: #e6edf3 !important; border-color: #2d333b !important; }
  input::placeholder, textarea::placeholder { color: #8b949e !important; }

  /* ====================================================================
     Footer (both React + legacy)
     ==================================================================== */
  [class*="PageFooter-desktop__Container"], [class*="PageFooter"][class*="Container"],
  [class*="PageFooter-shared"], footer, .footer, .page_footer {
    background-color: #0d1117 !important; border-color: #2d333b !important; color: #c4cdd6 !important; }
  [class*="PageFooter"] a, [class*="PageFooterArtistLinks__Link"],
  [class*="PageFooterHotSongLinks__Link"], [class*="PageFooter-desktop__Link"],
  footer a, .footer a { color: #9aa7f0 !important; }
  [class*="PageFooter-desktop__FinePrint"], [class*="PageFooter-desktop__Label"] { color: #8b949e !important; }
  [class*="PageFooterSocial__Slogan"] { color: #e6edf3 !important; }

  /* ---- Image loading placeholders: light-grey skeleton -> dark ---- */
  [class*="SizedImage__Container"], [class*="SizedImage__Image"],
  .clipped_background, .mini_card-thumbnail, .mini_article_card-thumbnail,
  .cover_art, .vertical_album_card-cover_art, [class*="image_with_overlay"] {
    background-color: #1c2128 !important; }

  /* ---- Ad surrounds: dark frame + dark loading slot, don't theme iframe content ---- */
  [class*="SectionLeaderboard__Container"], [class*="ChartHeader-desktop__AdContainer"],
  [class*="LyricsSidebarAd__"], [class*="SongCommentsWithAds__Footer"],
  .leaderboard, [id*="ad_"], [class*="dfp"], [class*="Leaderboard"] {
    background-color: #14181d !important; }
  /* Google DFP ad slots have stable ids — darken the empty/loading slot background */
  [id^="div-gpt-ad-"], [id*="google_ads_iframe"], [id$="__container__"], ins.adsbygoogle {
    background-color: #14181d !important; }
  /* Each DFP slot ships a sibling placeholder box (hashed styled-component class)
     that paints a light-grey #e9e9e9 rectangle while the slot is empty — a glaring
     light block in the lyrics column + leaderboards. It's always the next sibling
     of the [id^="div-gpt-ad-"] slot, so target it structurally. */
  [id^="div-gpt-ad-"] + div { background-color: #14181d !important; }

  /* ---- Misc ---- */
  hr { border-color: #2d333b !important; }
  ::selection { background-color: #ed4337 !important; color: #ffffff !important; }
  /* generic safety net: any element painted pure-white or near-white inline */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background:#fff"], [style*="background: #fff"],
  [style*="background-color:#fff"] { background-color: #1c2128 !important; }
}
